<?php
require_once dirname(__DIR__,2).'/app/notifications.php';
require_once dirname(__DIR__,2).'/app/bootstrap.php';secure_session();
$client=defined('TDC_GOOGLE_CLIENT_ID')?(string)TDC_GOOGLE_CLIENT_ID:(string)envv('TDC_GOOGLE_CLIENT_ID','');$secret=defined('TDC_GOOGLE_CLIENT_SECRET')?(string)TDC_GOOGLE_CLIENT_SECRET:(string)envv('TDC_GOOGLE_CLIENT_SECRET','');$redirect='https://tdctech.org/api/google-auth.php';
if(isset($_GET['config']))json_out(['available'=>$client!==''&&$secret!=='']);
if($client===''||$secret==='')json_out(['error'=>'Google sign-in needs the project OAuth client credentials and authorized redirect URI.'],503);
header('Referrer-Policy: no-referrer');header('Cache-Control: no-store');
if(!isset($_GET['code'])&&!isset($_GET['error'])){$_SESSION['google_state']=bin2hex(random_bytes(32));$_SESSION['google_started']=time();header('Location: https://accounts.google.com/o/oauth2/v2/auth?'.http_build_query(['client_id'=>$client,'redirect_uri'=>$redirect,'response_type'=>'code','scope'=>'openid email profile','state'=>$_SESSION['google_state'],'prompt'=>'select_account']));exit;}
$expected=$_SESSION['google_state']??'';$started=$_SESSION['google_started']??0;unset($_SESSION['google_state'],$_SESSION['google_started']);if(!$expected||!hash_equals($expected,(string)($_GET['state']??''))||time()-$started>600)json_out(['error'=>'Sign-in expired. Start again from the login page.'],400);if(isset($_GET['error'])){header('Location: /login');exit;}
function google_request(string $url,?array $data=null,?string $token=null):array{$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>8,CURLOPT_TIMEOUT=>20,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2]);if($data!==null)curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>http_build_query($data)]);if($token)curl_setopt($ch,CURLOPT_HTTPHEADER,['Authorization: Bearer '.$token]);$raw=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_RESPONSE_CODE);curl_close($ch);$out=json_decode((string)$raw,true);if($code!==200||!is_array($out))json_out(['error'=>'Google sign-in could not be verified. Retry from login.'],502);return $out;}
$token=google_request('https://oauth2.googleapis.com/token',['client_id'=>$client,'client_secret'=>$secret,'code'=>(string)$_GET['code'],'redirect_uri'=>$redirect,'grant_type'=>'authorization_code']);$profile=google_request('https://openidconnect.googleapis.com/v1/userinfo',null,(string)($token['access_token']??''));$email=strtolower((string)($profile['email']??''));$sub=(string)($profile['sub']??'');if(empty($profile['email_verified'])||!filter_var($email,FILTER_VALIDATE_EMAIL)||!preg_match('/^[0-9]{1,64}$/',$sub))json_out(['error'=>'Google must confirm your email address.'],403);
$pdo=db();$pdo->beginTransaction();try{$q=$pdo->prepare('SELECT id,email,google_sub,email_verified_at,status,role FROM users WHERE email=? OR google_sub=? FOR UPDATE');$q->execute([$email,$sub]);$u=$q->fetch();if($u){if($u['status']!=='active'){$pdo->rollBack();json_out(['error'=>'Account unavailable. Contact support.'],403);}if(($u['google_sub']&&$u['google_sub']!==$sub)||(!$u['google_sub']&&!$u['email_verified_at']&&(int)($_SESSION['uid']??0)!==(int)$u['id'])){$pdo->rollBack();json_out(['error'=>'Sign in with your existing password first, then use Google to link this account.'],409);}$pdo->prepare('UPDATE users SET google_sub=?,email_verified_at=COALESCE(email_verified_at,UTC_TIMESTAMP()) WHERE id=?')->execute([$sub,$u['id']]);$id=(int)$u['id'];$target=$u['role']==='admin'?'/admin/':'/dashboard';}else{$name=text_cut((string)($profile['name']??'Customer'),0,120);$pdo->prepare('INSERT INTO users(name,email,password_hash,google_sub,email_verified_at) VALUES(?,?,?,?,UTC_TIMESTAMP())')->execute([$name,$email,password_hash(bin2hex(random_bytes(32)),PASSWORD_DEFAULT),$sub]);$id=(int)$pdo->lastInsertId();$target='/dashboard';}$pdo->commit();session_regenerate_id(true);$_SESSION['uid']=$id;$_SESSION['csrf']=bin2hex(random_bytes(32));audit('account.google_login',$id);notify_successful_login($id);header('Location: '.$target);exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
